</div><div class="card-footer d-flex justify-content-between align-items-center"><button class="btn btn-outline-secondary" type="button" id="previous-block">Sebelumnya</button><span id="save-status" class="small text-muted">Draf tersimpan saat berpindah blok.</span><div><button class="btn btn-secondary" type="button" id="save-draft">Simpan Draf</button> <button class="btn btn-primary" type="button" id="next-block">Selanjutnya →</button><button class="btn btn-success d-none" type="submit" id="submit-report" formaction="{{ $public ? route('monitoring-akreditasi.public.submit',$token) : ($report ? route('monitoring-akreditasi.submit',$report) : route('monitoring-akreditasi.store')) }}" formmethod="POST">Tinjau & Kirim</button></div></div></div></section></div></form></div>
<script>
(()=>{const form=document.getElementById('monitoring-report-form'), buttons=[...document.querySelectorAll('[data-block]')], panels=[...document.querySelectorAll('[data-block-content]')], title=document.getElementById('block-title'), index=document.getElementById('block-index'), save=document.getElementById('save-status');let active=0;
function show(i){active=Math.max(0,Math.min(buttons.length-1,i));buttons.forEach((b,n)=>b.classList.toggle('active',n===active));panels.forEach((p,n)=>p.classList.toggle('d-none',n!==active));title.textContent=buttons[active].textContent.trim();index.textContent=active===0?'Panduan':`Blok ${active} dari 4`;document.getElementById('previous-block').disabled=active===0;document.getElementById('next-block').classList.toggle('d-none',active===buttons.length-1);document.getElementById('submit-report').classList.toggle('d-none',active!==buttons.length-1)}
async function saveDraft(){if(!form.reportValidity())return false;save.textContent='Menyimpan…';try{const response=await fetch(form.action,{method:'POST',headers:{'X-CSRF-TOKEN':form.querySelector('[name=_token]').value,'Accept':'application/json'},body:new FormData(form)});if(!response.ok)throw new Error(response.status===409?'Laporan berubah pada sesi lain. Salin jawaban lalu muat ulang.':'Gagal menyimpan. Periksa koneksi lalu coba lagi.');const data=await response.json();const version=form.querySelector('[name=edit_version]');if(version)version.value=data.edit_version;if(data.edit_url){window.location.href=data.edit_url;return false}save.textContent='Draf tersimpan.';return true}catch(e){save.textContent=e.message;return false}}
buttons.forEach((b,n)=>b.addEventListener('click',async()=>{if(n===0){show(n);return}if(await saveDraft())show(n)}));document.getElementById('previous-block').onclick=async()=>{if(active<=1){show(0);return}if(await saveDraft())show(active-1)};document.getElementById('next-block').onclick=async()=>{if(active===buttons.length-2){if(!confirm('Periksa kembali jawaban. Kirim laporan sekarang?'))return;show(active+1)}else if(await saveDraft())show(active+1)};document.getElementById('save-draft').onclick=saveDraft;
form.addEventListener('submit',async e=>{e.preventDefault();if(!confirm('Saya menyatakan data laporan ini benar. Kirim sekarang?'))return;const button=document.getElementById('submit-report');button.disabled=true;try{const response=await fetch(button.getAttribute('formaction'),{method:'POST',headers:{'X-CSRF-TOKEN':form.querySelector('[name=_token]').value,'Accept':'application/json'},body:new FormData(form)});if(!response.ok)throw new Error(response.status===409?'Laporan berubah pada sesi lain. Salin jawaban lalu muat ulang.':'Pengiriman gagal. Periksa jawaban dan koneksi.');if(@json($public)){document.open();document.write(await response.text());document.close()}else{window.location.href='{{ route('monitoring-akreditasi.index') }}'}}catch(error){button.disabled=false;save.textContent=error.message}});show(0)})();
</script>
